'use strict';

// VARIABLES //

var BACKEND = /^[a-z0-9]+(?:[._+-][a-z0-9]+)*$/;
var FIELDS = [
	'kind',
	'backend',
	'device_model',
	'runtime_version',
	'driver_version'
];
var KINDS = new Set([
	'cpu',
	'gpu',
	'tpu',
	'other'
]);


// FUNCTIONS //

/**
* Asserts that a value is a bounded, trimmed string.
*
* @private
* @param {*} value - value
* @param {string} field - field name
* @param {number} [maximum=512] - maximum length
*/
function requireString( value, field, maximum ) {
	maximum = maximum || 512;
	if ( typeof value !== 'string' || value.length === 0 || value.length > maximum || value !== value.trim() ) {
		throw new Error( field + ' must be a bounded, trimmed string' );
	}
}


// MAIN //

/**
* Validates structured execution-target metadata.
*
* @param {*} target - execution target
* @throws {Error} if the execution target is invalid
*/
function validateExecutionTarget( target ) {
	var keys;

	if ( !target || typeof target !== 'object' || Array.isArray( target ) ) {
		throw new Error( 'execution_target must be an object' );
	}
	keys = Object.keys( target );
	if ( !Object.hasOwn( target, 'kind' ) || keys.some( function unknown( field ) {
		return !FIELDS.includes( field );
	} ) ) {
		throw new Error( 'execution_target fields are malformed' );
	}
	requireString( target.kind, 'execution_target.kind', 16 );
	if ( !KINDS.has( target.kind ) ) {
		throw new Error( 'execution_target.kind is unsupported' );
	}
	if ( target.kind !== 'cpu' && !Object.hasOwn( target, 'backend' ) ) {
		throw new Error( 'execution_target.backend is required for non-CPU targets' );
	}
	if ( target.backend !== undefined ) {
		requireString( target.backend, 'execution_target.backend', 80 );
		if ( !BACKEND.test( target.backend ) ) {
			throw new Error( 'execution_target.backend must be a lowercase identifier' );
		}
	}
	['device_model', 'runtime_version', 'driver_version'].forEach( function validateField( field ) {
		if ( target[ field ] !== undefined ) {
			requireString( target[ field ], 'execution_target.' + field );
		}
	} );
}


// EXPORTS //

module.exports = validateExecutionTarget;
